//The PowerShell runtime that code generated by Convert-AzCmplyToWeb.ps1 runs on. Generated modules import R and call it
//for every operation whose PowerShell semantics differ from JavaScript.
import {
    ANULL, PSHashtable, ScriptBlock, PSRef, PSType, NamedArg, NativeObject, INT_KEY, PSVersion, isEnumerable, toArray
} from './types.js';
import { toStr, truthy, cast, normType } from './convert.js';
import * as ops from './ops.js';
import { getMember, setMember, index, setIndex, invokeMethod, staticMember, staticMethod, setVfs } from './members.js';
import {
    state, globalScope, scriptScope, defineFunction, callCommand, invokeTarget, errorRecord, throwValue, quietly, runScript, bind,
    runWithItem
} from './exec.js';
import { VFS } from './vfs.js';
import { parseJson, toJson } from './json.js';
import overrides from './overrides.js';

export { VFS, ANULL, parseJson, toJson };

export const R = state;

const typeCache = new Map();

Object.assign(R, {
    //output and enumeration
    u: ops.unwrap, e: ops.emit, a: ops.arrayOf, pi: ops.pipeItems, fi: ops.foreachItems, v: ops.val,
    pa: (O, items) => { for (let i = 0; i < items.length; i++) { O.push(items[i]); } },
    runItem: runWithItem,
    t: truthy, not: v => !truthy(v), str: toStr,
    //operators
    eq: ops.eq, ne: ops.ne, gt: ops.gt, ge: ops.ge, lt: ops.lt, le: ops.le,
    ceq: (l, r) => ops.eq(l, r, true), cne: (l, r) => ops.ne(l, r, true), cgt: (l, r) => ops.gt(l, r, true),
    cge: (l, r) => ops.ge(l, r, true), clt: (l, r) => ops.lt(l, r, true), cle: (l, r) => ops.le(l, r, true),
    match: ops.match, nmatch: ops.notMatch, cmatch: (S, l, r) => ops.match(S, l, r, true), cnmatch: (S, l, r) => ops.notMatch(S, l, r, true),
    like: ops.like, nlike: ops.notLike, clike: (l, r) => ops.like(l, r, true), cnlike: (l, r) => ops.notLike(l, r, true),
    rep: (l, r) => ops.replace(l, r, false, invokeReplacement), crep: (l, r) => ops.replace(l, r, true, invokeReplacement),
    split: ops.split, csplit: (l, r) => ops.split(l, r, true), splitU: ops.splitUnary, join: ops.join, joinU: ops.joinUnary,
    in: (l, r) => ops.inOp(l, r), nin: (l, r) => !ops.inOp(l, r), cin: (l, r) => ops.inOp(l, r, true), cnin: (l, r) => !ops.inOp(l, r, true),
    cont: (l, r) => ops.contains(l, r), ncont: (l, r) => !ops.contains(l, r), ccont: (l, r) => ops.contains(l, r, true), cncont: (l, r) => !ops.contains(l, r, true),
    is: (v, t) => ops.is(v, typeArg(t)), isnot: (v, t) => !ops.is(v, typeArg(t)),
    add: ops.add, sub: ops.sub, mul: ops.mul, div: ops.div, mod: ops.mod, neg: ops.neg,
    band: ops.band, bor: ops.bor, bxor: ops.bxor, bnot: ops.bnot, shl: ops.shl, shr: ops.shr,
    range: ops.range, fmt: ops.format,
    coalesce: (l, r) => (l === null || l === undefined || l === ANULL) ? r() : l,
    //members
    m: getMember, sm: setMember, i: index, si: setIndex, im: invokeMethod, st: staticMember, sc: staticMethod,
    c: (t, v) => cast(t, v),
    ty: name => { let t = typeCache.get(name); if (!t) { t = new PSType(name); typeCache.set(name, t); } return t; },
    //literals
    ht, pso,
    sb: (meta, body) => new ScriptBlock(meta, body),
    ref: (get, set) => new PSRef(get, set),
    //scopes, commands and errors
    G: globalScope, ss: scriptScope,
    def: defineFunction, cmd: callCommand, inv: invokeTarget,
    er: errorRecord, th: throwValue, quiet: quietly,
    mi: multiAssign, incv, incm, inci,
    env: () => null,
    //files and scripts
    file: registerFile, script: defineScript, runScript,
    configure
});

//R.np is called as R.np('Name') or R.np('Name', value): the arity tells a -Name:value argument from a plain -Name
R.np = function (name, value) { return new NamedArg(name, value, arguments.length > 1); };

function typeArg(t) { return t instanceof PSType ? t.name : toStr(t); }

function invokeReplacement(block, match) {
    const items = [];
    const S = Object.create(globalScope);
    S['_'] = match;
    block.body(S, items);
    return ops.unwrap(items);
}

//@{ k = v; ... } from a flat key/value list
function ht(kv, ordered = false) {
    const h = new PSHashtable(ordered);
    for (let i = 0; i < kv.length; i += 2) {
        if (h.has(kv[i])) { throw new Error(`Duplicate keys '${toStr(kv[i])}' are not allowed in hash literals.`); }
        h.set(kv[i], kv[i + 1]);
    }
    return h;
}

//[pscustomobject]@{ k = v; ... }: properties in literal order
function pso(kv) {
    const o = {};
    for (let i = 0; i < kv.length; i += 2) {
        const k = toStr(kv[i]);
        o[/^\d+$/.test(k) ? INT_KEY + k : k] = ops.val(kv[i + 1]);
    }
    return o;
}

//$a, $b, $c = value: the last variable gets the rest
function multiAssign(value, count) {
    const items = value === ANULL || value === null || value === undefined ? [] : (isEnumerable(value) ? toArray(value) : [value]);
    const out = [];
    for (let i = 0; i < count - 1; i++) { out.push(i < items.length ? items[i] : null); }
    const rest = items.slice(count - 1);
    out.push(rest.length === 0 ? null : rest.length === 1 ? rest[0] : rest);
    return out;
}

//++/-- on a variable, member or index; returns the value before (postfix) or after (prefix)
function incv(scope, name, delta, post) {
    const before = scope[name] ?? null;
    const after = ops.add(before, delta);
    scope[name] = after;
    return post ? ops.val(before) : after;
}
function incm(obj, name, delta, post) {
    const before = getMember(obj, name);
    const after = ops.add(before, delta);
    setMember(obj, name, after);
    return post ? before : after;
}
function inci(obj, key, delta, post) {
    const before = index(obj, key);
    const after = ops.add(before, delta);
    setIndex(obj, key, after);
    return post ? before : after;
}

//generated modules register their source file; statement positions are file index * 100000 + line
function registerFile(name) {
    let i = state.files.indexOf(name);
    if (i < 0) { i = state.files.length; state.files.push(name); }
    return i * 100000;
}

function defineScript(path, meta, body) {
    meta.file = path;
    return new ScriptBlock(meta, body);
}

const executionContext = new NativeObject('System.Management.Automation.EngineIntrinsics', {
    SessionState: new NativeObject('System.Management.Automation.SessionState', {
        Path: new NativeObject('System.Management.Automation.PathIntrinsics', {
            '#getunresolvedproviderpathfrompspath': p => state.vfs.resolve(toStr(p))
        })
    })
});

const versionTable = new PSHashtable(false);
versionTable.set('PSVersion', new PSVersion([7, 5, 0]));
versionTable.set('PSEdition', 'Core');

R.ctx = executionContext;
R.psv = versionTable;

function configure({ vfs, host } = {}) {
    if (vfs) { state.vfs = vfs; setVfs(vfs); }
    if (host) { state.host = host; }
}

state.overrides = overrides(R);

export { bind, normType };
